<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Appoint/project_list')}">项目名称列表</a>					<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Appoint/project_add', array('parentid' => $parentid))}','添加分类',480,260,true,false,false,addbtn,'add',true);">添加项目名称</a>					<a href="{pigcms{:U('Appoint/project_city_list')}" class="on">项目城市列表</a>					<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Appoint/project_city_add', array('parentid' => $parentid))}','添加分类',480,260,true,false,false,addbtn,'add',true);">添加项目城市</a>					<a href="{pigcms{:U('Appoint/project_import')}">项目名称导入</a>				</ul>			</div>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<th>编号</th>								<th>名称</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($project_list)">								<volist name="project_list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$vo.project_city_name}</td>										<td class="textcenter">											<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Appoint/project_city_edit',array('id'=>$vo['id']))}','编辑城市信息',480,260,true,false,false,editbtn,'edit',true);">编辑</a> | <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('Appoint/project_city_del')}">删除</a></td>										</td>									</tr>								</volist>							<else/>								<tr><td class="textcenter red" colspan="6">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/>